/**
 * Maintenance orders list (STRUCTURE §4). Filterable by status and type (corrective vs
 * preventive), keyset-paginated (D-014); row click opens the order workbench. "New" creates
 * a CORRECTIVE order only — PREVENTIVE orders are generated by a plan's run.
 */

import { Link, useNavigate } from "@tanstack/react-router";
import { useState } from "react";

import { formatDate } from "@/lib/format";
import { useMe } from "@/lib/session";
import { DataGrid, type DataGridColumn } from "@/components/DataGrid";
import { useEquipmentLookup, useMaintenanceOrders } from "@/modules/maintenance/hooks";
import type {
  MaintenanceOrder,
  MaintenanceOrderStatus,
  MaintenanceOrderType,
} from "@/modules/maintenance/types";

const STATUS_TONE: Record<MaintenanceOrderStatus, string> = {
  DRAFT: "bg-panel text-ink-muted",
  SCHEDULED: "bg-primary-tint text-primary",
  IN_PROGRESS: "bg-warn-tint text-warn",
  COMPLETED: "bg-success-tint text-success",
  CANCELLED: "bg-panel text-ink-muted",
};

export function OrderStatusChip({ status }: { status: MaintenanceOrderStatus }) {
  return (
    <span className={`rounded-[4px] px-1.5 py-0.5 text-[11px] font-semibold uppercase tracking-[0.02em] ${STATUS_TONE[status]}`}>
      {status.replace("_", " ")}
    </span>
  );
}

export function MaintenanceOrderListPage() {
  const navigate = useNavigate();
  const me = useMe();
  const canManage = (me.data?.permissions ?? []).includes("maintenance.order.manage");
  const [status, setStatus] = useState<MaintenanceOrderStatus | "">("");
  const [orderType, setOrderType] = useState<MaintenanceOrderType | "">("");

  const orders = useMaintenanceOrders({
    ...(status ? { status } : {}),
    ...(orderType ? { order_type: orderType } : {}),
  });
  const equipment = useEquipmentLookup();
  const rows = orders.data?.pages.flatMap((page) => page.items) ?? [];

  const equipmentLabel = (id: string) => {
    const unit = equipment.data?.items.find((e) => e.id === id);
    return unit ? `${unit.code} — ${unit.name}` : id;
  };

  const columns: DataGridColumn<MaintenanceOrder>[] = [
    { key: "order_number", header: "Order", render: (row) => row.order_number, width: "140px" },
    { key: "equipment", header: "Equipment", render: (row) => equipmentLabel(row.equipment_id) },
    { key: "order_type", header: "Type", render: (row) => row.order_type, width: "110px" },
    { key: "description", header: "Description", render: (row) => row.description },
    {
      key: "scheduled_date",
      header: "Scheduled",
      render: (row) => formatDate(row.scheduled_date),
      width: "120px",
    },
    { key: "status", header: "Status", render: (row) => <OrderStatusChip status={row.status} />, width: "120px" },
  ];

  const filterControl = "rounded-control border border-line bg-surface px-2 py-1.5 text-sm text-ink";

  return (
    <div>
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-semibold text-ink">Maintenance orders</h1>
        {canManage && (
          <Link
            to="/maintenance/orders/new"
            className="rounded-control bg-primary px-3 py-1.5 text-sm font-medium text-surface transition-colors duration-150 hover:bg-primary-strong"
          >
            New corrective order
          </Link>
        )}
      </div>

      <div className="mt-4 flex gap-2">
        <select
          value={status}
          onChange={(event) => setStatus(event.target.value as MaintenanceOrderStatus | "")}
          className={filterControl}
        >
          <option value="">All statuses</option>
          <option value="DRAFT">Draft</option>
          <option value="SCHEDULED">Scheduled</option>
          <option value="IN_PROGRESS">In progress</option>
          <option value="COMPLETED">Completed</option>
          <option value="CANCELLED">Cancelled</option>
        </select>
        <select
          value={orderType}
          onChange={(event) => setOrderType(event.target.value as MaintenanceOrderType | "")}
          className={filterControl}
        >
          <option value="">All types</option>
          <option value="CORRECTIVE">Corrective</option>
          <option value="PREVENTIVE">Preventive</option>
        </select>
      </div>

      <div className="mt-4">
        <DataGrid
          columns={columns}
          rows={rows}
          rowKey={(row) => row.id}
          onRowClick={(row) => void navigate({ to: "/maintenance/orders/$orderId", params: { orderId: row.id } })}
          loading={orders.isPending}
          emptyMessage="No maintenance orders. Create a corrective order, or run a preventive plan."
          hasMore={orders.hasNextPage}
          onLoadMore={() => void orders.fetchNextPage()}
          loadingMore={orders.isFetchingNextPage}
          label="Maintenance orders"
        />
      </div>
    </div>
  );
}
